import { z } from 'zod';

const MAX_PROMPT = 12000;
const MAX_RESPONSE = 1024 * 1024;
const REQUEST_TIMEOUT = 30000;

export const promptOptimizerMethods = {
  'prompts.optimize': {
    params: z.object({
      prompt: z.string().trim().min(1).max(MAX_PROMPT),
      context: z.enum(['general', 'ppt', 'ui']).optional(),
    }),
    result: z.object({ optimizedPrompt: z.string().min(1).max(MAX_RESPONSE) }),
  },
};

function endpointUrl(baseUrl, endpoint) {
  const url = new URL(baseUrl);
  if (url.protocol !== 'https:' && !(url.protocol === 'http:' && url.hostname === '127.0.0.1'))
    throw new Error('模型连接地址必须使用 HTTPS 或 loopback HTTP。');
  if (url.username || url.password || url.search || url.hash)
    throw new Error('模型连接地址不能包含凭据或查询参数。');
  const path = url.pathname.replace(/\/+$/u, '');
  url.pathname = path.endsWith(`/${endpoint}`) ? path : `${path}/${endpoint}`;
  return url;
}

async function readBody(response) {
  if (!response.body) return '';
  const reader = response.body.getReader();
  const chunks = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_RESPONSE) {
        await reader.cancel();
        throw new Error('Model response is too large.');
      }
      chunks.push(Buffer.from(value));
    }
  } finally { reader.releaseLock(); }
  return Buffer.concat(chunks, size).toString('utf8');
}

function textFromResponse(transport, payload) {
  if (transport === 'anthropic-messages') {
    const text = payload?.content?.filter(item => item?.type === 'text').map(item => item.text).join('');
    return typeof text === 'string' ? text : '';
  }
  if (transport === 'openai-responses') {
    if (typeof payload?.output_text === 'string') return payload.output_text;
    const output = Array.isArray(payload?.output) ? payload.output : [];
    return output.flatMap(item => Array.isArray(item?.content) ? item.content : [])
      .filter(item => item?.type === 'output_text' || item?.type === 'text')
      .map(item => item.text).filter(value => typeof value === 'string').join('');
  }
  const content = payload?.choices?.[0]?.message?.content;
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) return content.map(item => item?.text ?? '').join('');
  return '';
}

function systemInstruction(taskType) {
  const task = taskType === 'ppt' ? 'PPT 制作' : taskType === 'ui' ? '程序 UI 设计' : '一般任务';
  return [
    '你是专业的需求分析与提示词优化助手。',
    `当前任务类型：${task}。`,
    '请把用户的原始请求改写成清晰、可执行、专业的任务说明。保留原始意图、约束和已有事实，不要凭空增加产品承诺、技术能力或未提供的细节。',
    '补齐必要的目标、范围、交付物、验收标准和需要用户确认的信息；对缺失信息用明确的待确认项标注。',
    '需要用户补充关键信息时，要求执行代理调用结构化提问工具，每题提供 2–4 个有意义的可点选项，并始终允许单独自由输入。信息足够时直接执行。',
    '只输出改写后的请求正文，不要解释改写过程，不要使用 Markdown 代码围栏。',
  ].join('\n');
}

export async function optimizePrompt({ modelConnections }, request) {
  const taskType = request.context || 'general';
  const listed = modelConnections.list().connections;
  const selected = listed.find(connection => connection.enabled && connection.credentialConfigured && connection.defaultModel);
  if (!selected) {
    throw new Error('请先在“设置 → API 连接”配置一个已启用且有默认模型的连接。');
  }
  if (!selected.enabled || !selected.credentialConfigured)
    throw new Error('所选 API 连接未启用或尚未配置密钥。');
  const model = selected.defaultModel;
  if (!model) throw new Error('请先为所选 API 连接设置默认模型。');
  const resolved = modelConnections.resolveForRuntime(selected.id);
  const { apiKey, transport, baseUrl } = resolved;
  const userText = `原始请求：\n${request.prompt}`;
  const body = transport === 'anthropic-messages'
    ? {
      model, max_tokens: 4096, system: systemInstruction(taskType),
      messages: [{ role: 'user', content: userText }], stream: false,
    }
    : transport === 'openai-responses'
      ? { model, instructions: systemInstruction(taskType), input: userText, stream: false }
      : {
        model,
        messages: [{ role: 'system', content: systemInstruction(taskType) }, { role: 'user', content: userText }],
        temperature: 0.2, stream: false,
      };
  const headers = transport === 'anthropic-messages'
    ? { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' }
    : { Authorization: `Bearer ${apiKey}` };
  const endpoint = endpointUrl(baseUrl, transport === 'anthropic-messages' ? 'messages' : transport === 'openai-responses' ? 'responses' : 'chat/completions');
  let response;
  try {
    response = await fetch(endpoint, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(REQUEST_TIMEOUT),
      headers: { ...headers, 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(body),
    });
  } catch (error) {
    if (error?.name === 'TimeoutError') throw new Error('优化请求超时，请检查模型连接。');
    throw new Error('无法连接到模型服务，请检查连接地址和网络。');
  }
  const raw = await readBody(response);
  if (!response.ok) {
    let detail = '';
    try { detail = JSON.parse(raw)?.error?.message ?? JSON.parse(raw)?.message ?? ''; } catch {}
    throw new Error(`模型服务返回 HTTP ${response.status}${detail ? `：${String(detail).slice(0, 300)}` : '。'}`);
  }
  let payload;
  try { payload = JSON.parse(raw); } catch { throw new Error('模型服务返回了无效响应。'); }
  const optimizedPrompt = textFromResponse(transport, payload).trim();
  if (!optimizedPrompt) throw new Error('模型没有返回可用的优化结果。');
  return { optimizedPrompt: optimizedPrompt.slice(0, MAX_RESPONSE) };
}
